def monthly_fee(base_cents, months):
    if base_cents <= 0:
        raise ValueError("base_cents must be positive")
    if months <= 0:
        raise ValueError("months must be positive")
    return base_cents * months


def late_fee(amount_cents, days):
    if amount_cents <= 0:
        raise ValueError("amount_cents must be positive")
    if days <= 0:
        raise ValueError("days must be positive")
    return amount_cents * days // 100


def refund(amount_cents, percent):
    if amount_cents <= 0:
        raise ValueError("amount_cents must be positive")
    if percent <= 0:
        raise ValueError("percent must be positive")
    return amount_cents * percent // 100

