def normalize(key):
    """Canonical form of a cache key."""
    return key.strip().lower().split(":")[0]

--- cache.py ---
from keys import normalize


class Cache:
    def __init__(self):
        self._d = {}

    def put(self, key, value):
        self._d[key.strip().lower()] = value

    def get(self, key):
        return self._d.get(key.strip().lower())

    def invalidate(self, key):
        self._d.pop(normalize(key), None)

